# owner: platform
"""Find the stretches of opening hours nobody covers."""

from hourglass.models import Span
from hourglass.merging import merge_spans


def _clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"


def _label(begin: int, stop: int) -> str:
    text = f"{_clock(begin)}-{_clock(stop)}"
    return f"gap {text} ({stop - begin} min)"


def _holes(merged, opening):
    edges = [opening.start]
    for span in merged:
        edges += [span.start, span.end]
    edges.append(opening.end)
    pairs = zip(edges[0::2], edges[1::2])
    return [pair for pair in pairs if pair[0] < pair[1]]


def _check(merged, opening):
    for span in merged:
        if span.start < opening.start:
            raise ValueError(f"outside hours: {span}")
        if span.end > opening.end:
            raise ValueError(f"outside hours: {span}")


# ---
def find_gaps(worked, opening: Span):
    """Labels such as gap 12:00-13:00 (60 min), in order."""
    merged = merge_spans(worked)
    _check(merged, opening)
    holes = _holes(merged, opening)
    return [_label(*hole) for hole in holes]
